import type { Filter } from "@/lib/desk";
import { creditLimit, customerOutstanding } from "@/lib/selling";
import { lockErrors } from "@/lib/posting";
import { closeTasks, controlPolicy, correctionTasks, currentClosePeriod, openDisputes } from "@/lib/coreShared/controls";
import { CORE_DT } from "@/lib/coreShared/doctypes";
import type { Bi } from "./command";
import type { Impl, Placement, Run11Action } from "./run11";
import ROWS from "./run11Placements.generated.json";
import { ENTRIES } from "./run11Rollout";
import { listDrill, SPECS, type ChartBar, type ChartDef, type FigureUnit, type KpiDef, type KpiFnResult, type QueueDef, type RowPick, type SectionCtx, type SectionSpec } from "./sections";
import { stockValueGap } from "./stockReconciliation";
import { ksaVatReturn } from "@/lib/coreShared/ksaTax";
import type { Severity } from "./command";

/* ------------------------------------------------------------------ helpers ------------------------------------------------------------------ */
const co = (c: SectionCtx): Filter => ["company", "=", c.company];
const SUB: Filter = ["docstatus", "=", 1];
const DRAFT: Filter = ["docstatus", "=", 0];
const num = (v: unknown) => Number(v) || 0;
const str = (v: unknown) => (v == null ? "" : String(v));
const r2 = (x: number) => Math.round(x * 100) / 100;
const DAY = 86_400_000;
const days = (a: string, b: string) => (a && b ? Math.round((Date.parse(a.slice(0, 10)) - Date.parse(b.slice(0, 10))) / DAY) : 0);
const addDays = (iso: string, d: number) => new Date(Date.parse(iso) + d * DAY).toISOString().slice(0, 10);
const rowsOf = (d: Doc, f = "items") => (Array.isArray(d[f]) ? (d[f] as Doc[]) : []);
const since = (field: string, from: string): Filter => [field, ">=", from];
const upto = (field: string, to: string): Filter => [field, "<=", to];
const IN_USE = ["Sold", "Scrapped", "Capitalized", "Decapitalized", "Draft", "Cancelled"];

/** One evaluation shares derived sets (exposures, ledgers, percentiles) — keyed by the ctx object of that render. */
const MEMO = new WeakMap<SectionCtx, Map<string, unknown>>();
function once<T>(c: SectionCtx, key: string, f: () => T): T {
  let m = MEMO.get(c); if (!m) { m = new Map(); MEMO.set(c, m); }
  if (!m.has(key)) m.set(key, f());
  return m.get(key) as T;
}
const submitted = (dt: string, c: SectionCtx) => adapter.list(dt).filter((d) => Number(d.docstatus) === 1 && (!("company" in d) || d["company"] === c.company));
const accounts = (c: SectionCtx) => once(c, "acc", () => new Map(adapter.list("Account").filter((a) => a["company"] === c.company).map((a) => [a.name, a])));
const gl = (c: SectionCtx) => once(c, "gl", () => adapter.list("GL Entry").filter((g) => g["company"] === c.company && Number(g["is_cancelled"] ?? 0) !== 1 && str(g["posting_date"]) <= c.asOf));
const bankAccounts = (c: SectionCtx) => once(c, "bank", () => [...accounts(c).values()].filter((a) => a["account_type"] === "Bank" || a["account_type"] === "Cash").map((a) => a.name));
const warehouses = (c: SectionCtx) => once(c, "wh", () => adapter.list("Warehouse").filter((w) => w["company"] === c.company && !Number(w["is_group"])).map((w) => w.name));
const itemDoc = (code: string) => adapter.get("Item", code);
const itemGroup = (code: string) => str(itemDoc(code)?.["item_group"]) || "—";
const sle = (c: SectionCtx) => once(c, "sle", () => adapter.list("Stock Ledger Entry").filter((s) => s["company"] === c.company && Number(s["is_cancelled"] ?? 0) !== 1 && str(s["posting_date"]) <= c.asOf));
const lastMove = (c: SectionCtx, dir: "in" | "out") => once(c, `last-${dir}`, () => {
  const m = new Map<string, string>();
  for (const s of sle(c)) { const q = num(s["actual_qty"]); if (dir === "in" ? q <= 0 : q >= 0) continue; const k = `${s["item_code"]}|${s["warehouse"]}`; const d = str(s["posting_date"]); if (d > (m.get(k) ?? "")) m.set(k, d); }
  return m;
});
const binKey = (b: Doc) => `${b["item_code"]}|${b["warehouse"]}`;
const reorderLevel = (b: Doc) => num(rowsOf(itemDoc(str(b["item_code"])) ?? ({} as Doc), "reorder_levels").find((r) => r["warehouse"] === b["warehouse"])?.["warehouse_reorder_level"]);
const exposure = (c: SectionCtx, customer: string) => once(c, `exp:${customer}`, () => customerOutstanding(customer, c.company));
const limitOf = (c: SectionCtx, customer: string) => once(c, `lim:${customer}`, () => creditLimit(customer, c.company).limit);
const overLimit: RowPick = (d, c) => { const l = limitOf(c, d.name); return l > 0 && exposure(c, d.name) > l; };
const costRate = (code: string) => num(itemDoc(code)?.["valuation_rate"]) || num(adapter.list("Bin").find((b) => b["item_code"] === code && num(b["valuation_rate"]) > 0)?.["valuation_rate"]);
/** Gross margin of a sales invoice: net line amounts less quantity × incoming rate (falls back to the item's valuation rate). */
const margin = (si: Doc) => r2(rowsOf(si).reduce((t, r) => t + num(r["base_net_amount"] ?? r["net_amount"] ?? r["amount"]) - num(r["qty"]) * (num(r["incoming_rate"]) || costRate(str(r["item_code"]))), 0));
const unbilled = (d: Doc) => r2(num(d["base_grand_total"] ?? d["grand_total"]) * Math.max(0, 100 - num(d["per_billed"])) / 100);
const openValue = (d: Doc, per = "per_received") => r2(num(d["base_grand_total"] ?? d["grand_total"]) * Math.max(0, 100 - num(d[per])) / 100);
const jeDiff = (d: Doc) => r2(rowsOf(d, "accounts").reduce((t, r) => t + num(r["debit_in_account_currency"] ?? r["debit"]) - num(r["credit_in_account_currency"] ?? r["credit"]), 0));
const lockedUntil = (c: SectionCtx) => once(c, "lock", () => {
  const frozen = str(adapter.get("Company", c.company)?.["accounts_frozen_till_date"]);
  const pcv = submitted("Period Closing Voucher", c).map((p) => str(p["period_end_date"] ?? p["posting_date"])).sort().pop() ?? "";
  return [frozen, pcv].sort().pop() ?? "";
});
/** Books lock of posting.ts (Company frozen date, closed Accounting Period documents) plus the last Period Closing Voucher. */
const isLocked = (d: Doc, c: SectionCtx) => lockErrors("Journal Entry", d, str(d["posting_date"])).length > 0 || (!!lockedUntil(c) && str(d["posting_date"]) <= lockedUntil(c));
const jeErrors = (d: Doc, c: SectionCtx) => {
  const lines = rowsOf(d, "accounts");
  return !lines.length || Math.abs(jeDiff(d)) > 0.005 || lines.some((r) => { const t = accounts(c).get(str(r["account"]))?.["account_type"]; return (t === "Receivable" || t === "Payable") && !r["party"]; }) || isLocked(d, c);
};
const poItem = (c: SectionCtx) => once(c, "poi", () => new Map(submitted("Purchase Order", c).flatMap((po) => rowsOf(po).map((r) => [str(r["name"]), { po, r }] as const))));
const prItem = (c: SectionCtx) => once(c, "pri", () => new Map(submitted("Purchase Receipt", c).flatMap((pr) => rowsOf(pr).map((r) => [str(r["name"]), { pr, r }] as const))));
/** Three-way match of one supplier invoice against its order and receipt lines, using the company Control Policy tolerances. */
function matchType(pi: Doc, c: SectionCtx): "Matched" | "Price variance" | "Quantity variance" | "No receipt" {
  const p = controlPolicy(c.company); let price = false, qty = false, receipt = false, linked = false;
  for (const r of rowsOf(pi)) {
    const o = poItem(c).get(str(r["po_detail"])); const g = prItem(c).get(str(r["pr_detail"]));
    if (o || g || r["purchase_order"] || r["purchase_receipt"]) linked = true;
    if (g || r["purchase_receipt"]) receipt = true;
    if (o && num(o.r["rate"]) && Math.abs(num(r["rate"]) - num(o.r["rate"])) / num(o.r["rate"]) * 100 > p.price_tolerance_pct) price = true;
    const got = g ? num(g.r["qty"]) : o ? num(o.r["received_qty"]) : 0;
    if ((g || o) && got && (num(r["qty"]) - got) / got * 100 > p.qty_tolerance_pct) qty = true;
  }
  if (!linked && !Number(pi["update_stock"])) return "No receipt";
  if (!receipt && !Number(pi["update_stock"])) return "No receipt";
  return price ? "Price variance" : qty ? "Quantity variance" : "Matched";
}
const prOnTime = (pr: Doc, c: SectionCtx) => { const due = rowsOf(pr).map((r) => str(poItem(c).get(str(r["purchase_order_item"]))?.r["schedule_date"] ?? "")).filter(Boolean).sort()[0]; return due ? str(pr["posting_date"]) <= due : null; };
const prFromPo = (pr: Doc) => rowsOf(pr).some((r) => r["purchase_order"]);
const spend12 = (c: SectionCtx) => once(c, "spend", () => { const m = new Map<string, number>(); for (const pi of submitted("Purchase Invoice", c)) if (str(pi["posting_date"]) >= c.from12) m.set(str(pi["supplier"]), (m.get(str(pi["supplier"])) ?? 0) + num(pi["base_net_total"] ?? pi["net_total"])); return m; });
const assetCost = (a: Doc) => num(a["net_purchase_amount"] ?? a["gross_purchase_amount"] ?? a["purchase_amount"]);
const inUse: RowPick = (a) => Number(a.docstatus) === 1 && !IN_USE.includes(str(a["status"]));
const dueRows = (ads: Doc, before: string) => rowsOf(ads, "depreciation_schedule").filter((r) => !r["journal_entry"] && str(r["schedule_date"]) <= before);
const lastMovement = (c: SectionCtx) => once(c, "amv", () => { const m = new Map<string, string>(); for (const mv of submitted("Asset Movement", c)) for (const r of rowsOf(mv, "assets")) { const d = str(mv["transaction_date"]).slice(0, 10); if (d > (m.get(str(r["asset"])) ?? "")) m.set(str(r["asset"]), d); } return m; });
const repairs12 = (c: SectionCtx) => once(c, "rep", () => { const m = new Map<string, { n: number; cost: number }>(); for (const r of adapter.list("Asset Repair")) { if (r["company"] && r["company"] !== c.company) continue; if (Number(r.docstatus) === 2 || str(r["failure_date"]).slice(0, 10) < c.from12) continue; const k = str(r["asset"]); const v = m.get(k) ?? { n: 0, cost: 0 }; m.set(k, { n: v.n + 1, cost: v.cost + num(r["repair_cost"] ?? r["total_repair_cost"]) }); } return m; });
const bucketDays = (d: number, edges: [number, string][], last: string) => { for (const [e, k] of edges) if (d <= e) return k; return last; };
const pct = (a: number, b: number) => (b ? Math.round((a / b) * 1000) / 10 : 0);
const fig = (count: number, value: number, unit: FigureUnit, names?: string[]): KpiFnResult => ({ count, figure: { value: r2(value), unit }, ...(names ? { names } : {}) });

/* ------------------------------------------------------------------ formula table ------------------------------------------------------------------ */
type F = (c: SectionCtx) => Filter[];
interface FKpi { t: "kpi"; doctype: string; filters: F; f: Bi; label?: Bi; measure?: string; cur?: string; pick?: RowPick; value?: (d: Doc, c: SectionCtx) => number; unit?: FigureUnit; rate?: (c: SectionCtx) => { filters: Filter[]; pick?: RowPick }; fn?: (c: SectionCtx, user: string) => KpiFnResult; tone?: KpiDef["tone"] }
interface FChart { t: "chart"; doctype: string; filters: F; f: Bi; label?: Bi; kind?: "field" | "month"; field: string; tones?: Record<string, "ok" | "warn" | "bad" | "info">; measure?: string; cur?: string; pick?: RowPick; value?: (d: Doc, c: SectionCtx) => number; bucket?: (d: Doc, c: SectionCtx) => string; order?: string[]; sortKeys?: boolean; labels?: Record<string, Bi>; unit?: "qty"; fn?: (c: SectionCtx, user: string) => (Omit<ChartBar, "label"> & { label?: string })[] }
interface FQueue { t: "queue"; doctype: string; filters: F; f: Bi; label?: Bi; date: string; party?: string; amount?: string; cur?: string; order?: "asc" | "desc"; action: Bi; severity: Severity; overdue?: boolean; pick?: RowPick; dateOf?: (d: Doc) => string; amountOf?: (d: Doc) => number | null; partyOf?: (d: Doc) => string }
interface FAdopt { t: "adopt"; bind: string; f: Bi }
interface FAction { t: "action"; kind: "native-new" | "list" | "tool" | "pro" | "report" | "tab"; doctype?: string; filters?: F; to?: string; report?: string; how: Bi }
interface FDoc { t: "doc"; f: Bi }
export type Formula = FKpi | FChart | FQueue | FAdopt | FAction | FDoc;

const K = (doctype: string, filters: F, f: Bi, o: Partial<FKpi> = {}): FKpi => ({ t: "kpi", doctype, filters, f, ...o });
const CH = (doctype: string, filters: F, field: string, f: Bi, o: Partial<FChart> = {}): FChart => ({ t: "chart", doctype, filters, field, f, ...o });
const Q = (doctype: string, filters: F, date: string, f: Bi, action: Bi, severity: Severity, o: Partial<FQueue> = {}): FQueue => ({ t: "queue", doctype, filters, date, f, action, severity, ...o });
const AD = (bind: string, f: Bi): FAdopt => ({ t: "adopt", bind, f });
const AC = (kind: FAction["kind"], how: Bi, o: Partial<FAction> = {}): FAction => ({ t: "action", kind, how, ...o });

const DUE_W: Record<string, Bi> = { overdue: ["Overdue", "متأخر"], w1: ["This week", "هذا الأسبوع"], w2: ["Next week", "الأسبوع القادم"], w4: ["In 2–4 weeks", "خلال 2–4 أسابيع"], later: ["Later", "لاحقًا"] };
const dueWeek = (due: string, asOf: string) => { const d = days(due, asOf); return d < 0 ? "overdue" : d <= 7 ? "w1" : d <= 14 ? "w2" : d <= 28 ? "w4" : "later"; };
const AGE: Record<string, Bi> = { a7: ["0–7 days", "0–7 أيام"], a30: ["8–30 days", "8–30 يومًا"], a60: ["31–60 days", "31–60 يومًا"], a90: ["61–90 days", "61–90 يومًا"], a180: ["91–180 days", "91–180 يومًا"], old: ["Older", "أقدم"] };
const ageKey = (d: number) => bucketDays(d, [[7, "a7"], [30, "a30"], [60, "a60"], [90, "a90"], [180, "a180"]], "old");

