const vatAccounts = (c: SectionCtx) => once(c, "vat", () => [...accounts(c).values()].filter((a) => a["account_type"] === "Tax" && /vat|value added|ضريبة القيمة/i.test(`${a.name} ${str(a["account_name"])}`)).map((a) => a.name));
