  return [...m].sort((a, b) => b[1].v - a[1].v).slice(0, 8).map(([k, x]) => ({ key: k, label: k, count: x.names.size, value: r2(x.v), drill: listDrill("Sales Invoice", [co(c), SUB, ["name", "in", [...x.names]]]) }));
