    if (a["company"] !== c.company || !inUse(a, c)) continue;
    const cat = adapter.get("Asset Category", str(a["asset_category"]));
    const acc = str(rowsOf(cat ?? ({} as Doc), "accounts").find((r) => r["company_name"] === c.company)?.["fixed_asset_account"] ?? "");
    if (acc) byAcc.set(acc, (byAcc.get(acc) ?? 0) + assetCost(a));
