function rollForward(c: SectionCtx): (Omit<ChartBar, "label"> & { label?: string })[] {
  const [from, to] = fyRange(c);
  const as = adapter.list("Asset").filter((a) => a["company"] === c.company && Number(a.docstatus) === 1);
  const opening = as.filter((a) => str(a["purchase_date"]) < from && !(str(a["disposal_date"]) && str(a["disposal_date"]) < from));
  const added = as.filter((a) => str(a["purchase_date"]) >= from && str(a["purchase_date"]) <= to);
  const disposed = as.filter((a) => str(a["disposal_date"]) >= from && str(a["disposal_date"]) <= to);
  const depRows = adapter.list("Asset Depreciation Schedule").filter((s) => s["company"] === c.company && Number(s.docstatus) === 1).flatMap((s) => rowsOf(s, "depreciation_schedule").filter((r) => r["journal_entry"] && str(r["schedule_date"]) >= from && str(r["schedule_date"]) <= to));
  const dep = depRows.reduce((t, r) => t + num(r["depreciation_amount"]), 0);
  const closing = as.filter((a) => inUse(a, c)).reduce((t, a) => t + num(a["value_after_depreciation"]), 0);
  const sum = (xs: Doc[]) => r2(xs.reduce((t, a) => t + assetCost(a), 0));
  const d = (names: Doc[]) => listDrill("Asset", [co(c), SUB, ["name", "in", names.map((a) => a.name)]]);
  return [
    { key: "open", label: "open", count: opening.length, value: sum(opening), drill: d(opening) },
    { key: "add", label: "add", count: added.length, value: sum(added), drill: d(added) },
    { key: "disp", label: "disp", count: disposed.length, value: -sum(disposed), drill: d(disposed) },
    { key: "dep", label: "dep", count: depRows.length, value: -r2(dep), drill: listDrill("Journal Entry", [co(c), SUB, ["voucher_type", "=", "Depreciation Entry"], ["posting_date", "between", [from, to]]]) },
    { key: "close", label: "close", count: as.filter((a) => inUse(a, c)).length, value: r2(closing), drill: d(as.filter((a) => inUse(a, c))) },
  ];
}
/** Rows' amounts that depend on the evaluating ctx are refreshed before each workspace evaluation. */
function primeLasts(c: SectionCtx) {
  todayAsOf = c.asOf;
  for (const cu of adapter.list("Customer")) { const l = limitOf(c, cu.name); if (l > 0) expLast.set(cu.name, r2(exposure(c, cu.name) - l)); }
  sales12(c); overdueBy(c); marginDrop(c);
  for (const [k, v] of spend12(c)) spendLast.set(k, r2(v));
  for (const [k, v] of repairs12(c)) repairLast.set(k, v.cost);
}

/* ------------------------------------------------------------------ application ------------------------------------------------------------------ */
type Row = [id: string, type: string, ws: string, label: string, target: string];
const SHEET = new Map((ROWS as unknown as Row[]).map((r) => [r[0], r]));
const wsOf = (id: string) => SHEET.get(id)?.[2] ?? (/-BI-\d+$/.test(id) ? id.split("-").slice(0, 2).join("-") : id.split("-").slice(1, 3).join("-"));
const labelOf = (id: string, f: Formula): Bi => ("label" in f && f.label) ? f.label : [SHEET.get(id)?.[3] ?? id, ENTRIES[id]?.[0] ?? SHEET.get(id)?.[3] ?? id];
export const formulaKey = (id: string) => `r11-${id.toLowerCase()}`;

/** A placement with its defined formula: no longer pending; bound to the element that now shows it. */
export function applyFormula(p: Placement): Placement {
  const f = FORMULAS[p.id]; if (!f) return p;
  const { note: _n, server: _s, ...base } = p; void _n; void _s;
  const done = (impl: Impl, binds: string[], note?: Bi): Placement => ({ ...base, impl, binds, ...(note ? { note } : {}) });
  switch (f.t) {
    case "kpi": return done("FRONTEND_PRESENT", [`kpi:${formulaKey(p.id)}`], f.f);
    case "chart": return done("FRONTEND_PRESENT", [`chart:${formulaKey(p.id)}`], f.f);
    case "queue": return done("FRONTEND_PRESENT", [`run11q:${formulaKey(p.id)}`], f.f);
    case "adopt": return done("PRESERVE_EXISTING", [f.bind], f.f);
    case "action": return done(f.kind === "pro" || f.kind === "tab" ? "FRONTEND_PRESENT" : "NATIVE_AVAILABLE", [`action:${p.id}`]);
    case "doc": return done("FRONTEND_PRESENT", p.binds, f.f);
  }
}
/** The contextual action with its defined target (policy / missing / server actions become real ones). */
export function applyAction(a: Run11Action): Run11Action {
  const f = FORMULAS[a.id]; if (!f || f.t !== "action") return a;
  const { server: _s, ...rest } = a; void _s;
  return { ...rest, how: f.how, kind: f.kind, ...(f.doctype ? { doctype: f.doctype } : {}), ...(f.filters ? { filters: f.filters } : {}), ...(f.to ? { to: f.to } : {}), ...(f.report ? { report: f.report } : {}) };
}
const ids = (ws: string, t: Formula["t"]) => Object.entries(FORMULAS).filter(([id, f]) => f.t === t && wsOf(id) === ws).map(([id]) => id);
export function formulaKpis(ws: string, c: SectionCtx): KpiDef[] {
  return ids(ws, "kpi").map((id) => { const f = FORMULAS[id] as FKpi; const r = f.rate?.(c);
    return { id: formulaKey(id), label: labelOf(id, f), hint: f.f, doctype: f.doctype, filters: f.filters(c), ...(f.measure ? { measure: f.measure } : {}), ...(f.cur ? { cur: f.cur } : {}), ...(f.tone ? { tone: f.tone } : {}), ...(f.pick ? { pick: f.pick } : {}), ...(f.value ? { value: f.value } : {}), ...(f.unit ? { unit: f.unit } : {}), ...(r ? { rate: r } : {}), ...(f.fn ? { fn: f.fn } : {}) }; });
}
export function formulaCharts(ws: string, c: SectionCtx): ChartDef[] {
  return ids(ws, "chart").map((id) => { const f = FORMULAS[id] as FChart;
    return { id: formulaKey(id), label: labelOf(id, f), kind: f.kind ?? "field", doctype: f.doctype, filters: f.filters(c), field: f.field, ...(f.measure ? { measure: f.measure } : {}), ...(f.cur ? { cur: f.cur } : {}), ...(f.pick ? { pick: f.pick } : {}), ...(f.value ? { value: f.value } : {}), ...(f.bucket ? { bucket: f.bucket } : {}), ...(f.order ? { order: f.order } : {}), ...(f.sortKeys ? { sortKeys: true } : {}), ...(f.labels ? { labels: f.labels } : {}), ...(f.tones ? { tones: f.tones } : {}), ...(f.unit ? { unit: f.unit } : {}), ...(f.fn ? { fn: f.fn } : {}) }; });
}
export function formulaQueues(ws: string, c: SectionCtx): QueueDef[] {
  primeLasts(c);
  return ids(ws, "queue").map((id) => { const f = FORMULAS[id] as FQueue;
    return { id: formulaKey(id), label: labelOf(id, f), doctype: f.doctype, filters: f.filters(c), date: f.date, action: f.action, severity: f.severity, ...(f.party ? { party: f.party } : {}), ...(f.amount ? { amount: f.amount } : {}), ...(f.cur ? { cur: f.cur } : {}), ...(f.order ? { order: f.order } : {}), ...(f.overdue ? { overdueFrom: c.asOf } : {}), ...(f.pick ? { pick: f.pick } : {}), ...(f.dateOf ? { dateOf: f.dateOf } : {}), ...(f.amountOf ? { amountOf: f.amountOf } : {}), ...(f.partyOf ? { partyOf: f.partyOf } : {}) }; });
}
const SPEC_CACHE = new Map<string, SectionSpec>();
/** The workspace section spec with its Run11.1 defined-formula figures appended (original SPECS stay the exported contract). */
export function workspaceSpec(ws: string): SectionSpec | undefined {
  const base = SPECS[ws]; if (!base) return undefined;
  const hit = SPEC_CACHE.get(ws); if (hit) return hit;
  const spec: SectionSpec = { ...base, kpis: (c) => [...base.kpis(c), ...formulaKpis(ws, c)], charts: (c) => [...base.charts(c), ...formulaCharts(ws, c)] };
  SPEC_CACHE.set(ws, spec);
  return spec;
}
